using System;
using Azure;

class Program
{
    static void Main()
    {
        var t = typeof(ResponseError);
        Console.WriteLine($"Type: {t.FullName}");
        Console.WriteLine($"Interface count: {t.GetInterfaces().Length}");
        foreach (var iface in t.GetInterfaces())
        {
            Console.WriteLine($"  {iface}");
        }
        // Check attrs
        var attrs = t.GetCustomAttributes(typeof(System.Text.Json.Serialization.JsonConverterAttribute), false);
        foreach (var a in attrs)
        {
            var jca = (System.Text.Json.Serialization.JsonConverterAttribute)a;
            Console.WriteLine($"JsonConverter: {jca.ConverterType}");
        }
    }
}
EOF
